#!/usr/bin/env python3
"""Static site builder. Run: python3 build.py -> dist/"""
import json,os,shutil,html
TREES=open('src/treeline.svg.html').read()
SITE="https://garettoswald9999.github.io/family-funding-tools"
NAME="Family Funding & Tools"
NL_URL="https://assets.mailerlite.com/jsonp/2720821/forms/201603881613920183/subscribe"
SB_URL="https://assets.mailerlite.com/jsonp/2720821/forms/201603907061810930/subscribe"
PRIV='<p class="priv">We only use your email to send these updates. Unsubscribe anytime.</p>'
SHARE='<section class="share" aria-label="Share" data-url="{url}" data-text="{text}"><h2>Know another parent who needs this?</h2><p><button type="button" class="pill lg share-native">Share with another parent</button></p><p class="share-links"><button type="button" class="chip share-copy">Copy link</button><a class="chip" rel="noopener" target="_blank" data-net="x" href="#">X</a><a class="chip" rel="noopener" target="_blank" data-net="fb" href="#">Facebook</a><a class="chip" rel="noopener" target="_blank" data-net="wa" href="#">WhatsApp</a><a class="chip" data-net="sms" href="#">Text message</a></p><output class="share-out" aria-live="polite"></output></section>'
def mlform(url,fid,btn,label="Email"):
    return f'<form class="nl-form ml-form" action="{url}" method="post"><label for="{fid}">{label}</label><input id="{fid}" type="email" name="fields[email]" required autocomplete="email" placeholder="you@example.com"><input type="hidden" name="ml-submit" value="1"><input type="hidden" name="anticsrf" value="true"><button type="submit" class="pill">{btn}</button><output aria-live="polite"></output></form>'+PRIV
E=html.escape
P=json.load(open('data/programs.json')); P+=[x for x in json.load(open('data/provinces/bc.json'))['programs'] if x['slug'] not in {p['slug'] for p in P}]; L=sorted(json.load(open('data/listings.json')),key=lambda l:not l.get('pinned'))
D='dist'; shutil.rmtree(D,ignore_errors=True); os.makedirs(D)
urls=[]
def page(path,title,desc,body,ld=None,og='og-home.png'):
    depth=path.count('/'); r='../'*depth
    lds=''.join(f'<script type="application/ld+json">{json.dumps(x,ensure_ascii=False)}</script>' for x in (ld or []))
    nav=f'<a href="{r}funding/index.html">Funding Guide</a><a href="{r}directory/index.html">Directory</a><a href="{r}quiz.html">Quiz</a><a class="pill sm" href="{r}submit.html">Get Listed</a><a class="prov-pill" href="{r}provinces/index.html" data-prov-pill aria-label="Pick your province"><span aria-hidden="true">📍</span> <span class="pv">Province</span></a>'
    canon=SITE+'/'+path.replace('index.html','')
    h=f'''<!DOCTYPE html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f1f17"><meta name="color-scheme" content="dark"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{canon}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canon}"><meta property="og:site_name" content="{E(NAME)}"><meta property="og:image" content="{SITE}/og/{og}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="{E(title)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{E(title)}"><meta name="twitter:description" content="{E(desc)}"><meta name="twitter:image" content="{SITE}/og/{og}"><link rel="stylesheet" href="{r}style.css">{lds}</head><body><a class="skip" href="#main">Skip to content</a><header class="topnav"><div class="wrap"><a class="brand" href="{r}index.html"><span role="img" aria-label="Canada">🇨🇦</span> Family Funding &amp; Tools</a><nav aria-label="Main">{nav}</nav></div></header><main id="main">{body}</main><footer>{TREES}<div class="wrap"><section class="signup" id="newsletter" aria-labelledby="nl"><h2 id="nl">Weekly newsletter</h2><p>One short email a week. Free.</p>{mlform(NL_URL,'em-'+str(depth)+str(len(urls)),'Sign up')}</section><p class="disc">General info, not legal or financial advice. Always check the official link. <a href="{r}faq.html">FAQ</a> · <a href="{r}about.html">About</a> · <a href="{r}disclaimer.html">Disclaimer</a> · <a href="{r}credits.html">Credits</a></p><p class="disc"><span role="img" aria-label="Canada">🇨🇦</span> Made in Chilliwack, BC. Header photo: <a href="https://commons.wikimedia.org/wiki/File:Mt._Cheam_BC.png">Mt. Cheam</a> by Agassizlabs, CC0, via Wikimedia Commons.</p></div></footer><script src="{r}province.js"></script><script src="{r}forms.js"></script><script src="{r}share.js"></script></body></html>'''
    os.makedirs(os.path.dirname(os.path.join(D,path)) or D,exist_ok=True)
    open(os.path.join(D,path),'w').write(h); urls.append(canon)
def ul(xs): return '<ul>'+''.join(f'<li>{E(x)}</li>' for x in xs)+'</ul>'
# programs
import provinces
PROV,PROVSEL=provinces.build(page,E,SITE,{p['slug'] for p in P})
def provbox(r,h='h2'):
    pr=PROV['bc']
    li=''.join(f'<li class="card"><h3><a href="{r}{x["url"]}">{E(x["nickname"])}</a></h3><p>{E(x["what"])}</p><p class="amt{"" if x["verified"] else " unv"}">{E(x["amount_short"])}</p></li>' for x in pr['programs'])
    return f'<section class="prov-box" aria-labelledby="pb-{h}"><div class="prov-head"><{h} id="pb-{h}">Help in <span data-prov-name>British Columbia</span></{h}><label>Change province<select class="prov-select">{PROVSEL}</select></label></div><p class="note prov-guess"></p><ul class="grid prov-list">{li}</ul><p><a class="prov-more" href="{r}provinces/bc/index.html">See all British Columbia programs ›</a></p></section>'

cards='<li class="card"><h3><a href="dtc/index.html">DTC Playbook</a> <span class="badge">New</span></h3><p>Apply, describe daily life, doctor fees, MP help, and up to 10 years of back pay.</p></li><li class="card"><h3><a href="autism-funding-2027.html">Autism Funding ends March 31, 2027</a> <span class="badge warn">Deadline</span></h3><p>What replaces it and what to do now.</p></li>'
for p in P:
    links='<ul>'+''.join(f'<li><a href="{u}" rel="noopener">{E(t)}</a></li>' for t,u in p['links'])+'</ul>'
    b=f'<p class="crumb"><a href="index.html">Funding Guide</a></p><h1>{E(p["name"])}</h1><p class="gov">{E(p["gov"])}</p><h2>What it is</h2><p>{E(p["what"])}</p><h2>How much</h2><p>{E(p["amount"])}</p><h2>Who can get it</h2>{ul(p["who"])}<h2>How to apply</h2><ol>'+''.join(f'<li>{E(s)}</li>' for s in p['steps'])+f'</ol><h2>What to have ready</h2>{ul(p["docs"])}<h2>Official links</h2>{links}<p><a class="pill" href="../quiz.html">Take the eligibility quiz</a></p>'
    ld=[{"@context":"https://schema.org","@type":"HowTo","name":"How to apply for "+p['name'],"description":p['what'],"step":[{"@type":"HowToStep","position":i+1,"text":s} for i,s in enumerate(p['steps'])]}]
    page(f'funding/{p["slug"]}.html',f'{p["name"]}: BC parent guide',p['what'][:155],b,ld)
    cards+=f'<li class="card"><h3><a href="{p["slug"]}.html">{E(p["name"])}</a></h3><p>{E(p["what"][:140])}…</p></li>'
page('funding/index.html','Funding Guide for Canadian families of kids with disabilities (BC and all provinces)','Plain-language guide to the DTC, Child Disability Benefit, RDSP, BC Autism Funding, Jordan\'s Principle, and programs in every province and territory.',f'<div class="head"><h1>Funding Guide.</h1><p class="sub">Simple guides to money and help for your child. <a href="../quiz.html">Not sure where to start? Take the 2-minute quiz.</a></p></div>{provbox("../")}<h2>Guides</h2><ul class="grid">{cards}</ul><h2>Other provinces and territories</h2><ul class="grid">'+''.join(f'<li class="card"><h3><a href="../provinces/{c}/index.html">{E(PROV[c]["name"])}</a></h3><p>{len(PROV[c]["programs"])} programs</p></li>' for c in provinces.ORDER if c!='bc')+'</ul>')
# directory
cats=sorted({l['category'] for l in L}); regs=sorted({l['region'] for l in L})
def site_dd(l):
    x=''
    if l.get('status'): x+=f'<dt>Status</dt><dd><span class="badge">Coming soon</span> {E(l["status"])}</dd>'
    if l.get('owner_disclosure'): x+=f'<dt>Disclosure</dt><dd>{E(l["owner_disclosure"])}</dd>'
    u=l['url'] or l.get('app_store_url')
    x+=f'<dt>Official site</dt><dd><a href="{u}" rel="noopener nofollow">{E(u)}</a></dd>' if u else '<dt>App Store</dt><dd>Link coming at launch.</dd>'
    return x
def rel(l): return "This app is made by the founder of this site." if l.get('owner_disclosure') else "We don\'t sell this product and have no relationship with this organization."
for l in L:
    sbx=('<section class="feature sb-form" aria-label="Get notified"><h2>Get notified</h2>'+mlform(SB_URL,'sb-page','Get notified','Email me when Speakboard launches')+'</section>') if l['slug']=='speakboard' else ''
    b=f'<p class="crumb"><a href="index.html">Directory</a> › {E(l["category"])}</p><h1>{E(l["name"])}</h1><p>{E(l["description"])}</p><dl><dt>Category</dt><dd>{E(l["category"])}</dd><dt>Region</dt><dd>{E(l["region"])}</dd><dt>Price</dt><dd>{E(l["price"])}</dd><dt>Can BC Autism Funding pay for it?</dt><dd>{E(l["funding_eligible"])}<br><small>{E(l["funding_note"])}</small></dd>{site_dd(l)}<dt>Last checked</dt><dd>{l["checked"]}</dd></dl><p class="note">{rel(l) if l.get("owner_disclosure") else rel(l)+' Prices and details: see the official site. <a href="../submit.html">Is this your listing?</a>'}</p>{sbx}'
    ld=[{"@context":"https://schema.org","@type":"Organization" if l['category'] in('Support groups & organizations','BC autism service providers') else "Product","name":l['name'],"description":l['description'],**({"url":l['url']} if l['url'] else {})}]
    page(f'directory/{l["slug"]}.html',f'{l["name"]}: {l["category"]}',l['description'][:155],b,ld)
badge=lambda l:' <span class="badge">Coming soon</span>' if l.get('status') else ''
disc=lambda l:'<p class="owner">'+E(l['owner_disclosure'])+'</p>' if l.get('owner_disclosure') else ''
fundtag=lambda l:'<span>May qualify for Autism Funding</span>' if l['funding_eligible'].startswith('Possibly') else ''
opt=lambda xs:''.join(f'<option>{E(x)}</option>' for x in xs)
items=''.join(f'<li class="card{' pinned' if l.get('pinned') else ''}" data-cat="{E(l["category"])}" data-reg="{E(l["region"])}" data-price="{l["price"]}" data-fund="{"y" if l["funding_eligible"].startswith("Possibly") else "n"}"><h3><a href="{l["slug"]}.html">{E(l["name"])}</a>{badge(l)}</h3><p>{E(l["description"])}</p>{disc(l)}<p class="tags"><span>{l["price"]}</span>{fundtag(l)}</p></li>' for l in L)
chiphtml=''.join(f'<button type="button" class="chip" data-cat="{E(c)}" aria-pressed="false">{E(c)}</button>' for c in cats)
dirb=f'''<div class="head"><h1>Directory.</h1><p class="sub">Tools and services for families. Tap a category.</p></div><div class="filters" role="search" aria-label="Filter listings"><div class="chips" role="group" aria-label="Category"><button type="button" class="chip" data-cat="" aria-pressed="true">All</button>{chiphtml}</div><label class="search">Search<input id="f-q" type="search" placeholder="Search tools"></label><details class="more"><summary>More filters</summary><div class="row"><label>Region<select id="f-reg"><option value="">All regions</option>{opt(regs)}</select></label><label>Price<select id="f-price"><option value="">Any price</option><option>Free</option><option>Paid</option><option>Varies</option></select></label><label class="check"><input type="checkbox" id="f-fund"> May qualify for Autism Funding</label></div></details></div><p id="count" aria-live="polite"></p><ul class="grid" id="list">{items}</ul><p class="note">“May qualify for Autism Funding” is our best reading of BC rules, not a promise. Check with the Autism Funding Branch first.</p><script src="../directory.js"></script>'''
page('directory/index.html','Canadian autism & special-needs tools directory','Directory of AAC apps, sensory and safety products, BC autism service providers and support groups, with Autism Funding notes.',dirb,[{"@context":"https://schema.org","@type":"ItemList","itemListElement":[{"@type":"ListItem","position":i+1,"name":l['name'],"url":f"{SITE}/directory/{l['slug']}.html"} for i,l in enumerate(L)]}])
json.dump(L,open(f'{D}/listings.json','w'),ensure_ascii=False); json.dump(PROV,open(f'{D}/provinces.json','w'),ensure_ascii=False)
# home
EXF=[('When does BC Autism Funding end?', 'The Autism Funding program ends March 31, 2027. Families already getting it keep getting it until then.'), ('Can new families still apply?', 'Yes. You can apply for Autism Funding until March 2027. The steps and rules are the same as before.'), ('What replaces it?', 'Two new programs. The BC Children and Youth Disability Benefit is based on how much help your child needs. The Children and Youth Disability Supplement is based on your family’s income.'), ('How much is the new Disability Benefit?', "$6,500 a year, or up to $17,000 a year for kids who need the most help. It depends on your child’s needs, not your income. Any diagnosis can count. Once your child qualifies, it lasts until age 19."), ('How much is the new Disability Supplement?', 'Up to $6,000 a year per child, paid each month with the Canada Child Benefit, up to age 18. You get it by itself if: your child is approved for the Disability Tax Credit, your family income is under the limit, and you file your taxes. First payments start July 2027. They are based on your 2026 tax return.'), ('Do I have to do anything?', 'The ministry says it will contact every family in Autism Funding before March 31, 2027, about whether they can get the Disability Benefit.')]
exb='<p class="crumb"><a href="index.html">Funding Guide</a></p><h1>BC Autism Funding ends March 31, 2027. Here\'s what replaces it.</h1><p class="sub left">The short version for busy parents. Facts from gov.bc.ca, checked 2026-10-17.</p><div class="sumcard"><div><strong>Now – March 2027</strong><span>Autism Funding keeps going. Under 6: up to $22,000 a year. Ages 6 to 18: up to $6,000 a year. You can still apply.</span></div><div><strong>New: Disability Benefit</strong><span>$6,500, or up to $17,000 a year, based on how much help your child needs. Any diagnosis. Until age 19.</span></div><div><strong>New: Disability Supplement</strong><span>Up to $6,000 a year per child, based on family income. Paid monthly from July 2027. Your child needs the DTC.</span></div></div><h2>Do these 4 things now</h2><ol class="steps"><li><strong>Apply for the Disability Tax Credit</strong> if you haven\'t. The new supplement needs it. <a href="disability-tax-credit.html">How</a></li><li><strong>File your 2026 taxes</strong> (both parents), even with no income. July 2027 payments are based on them.</li><li><strong>Diagnosed but not enrolled?</strong> Apply for Autism Funding before March 2027. <a href="autism-funding.html">How</a></li><li><strong>Watch your mail</strong> for the ministry letter about the Disability Benefit.</li></ol>'+''.join(f'<h2>{E(q)}</h2><p>{E(a)}</p>' for q,a in EXF)+'<h2>Official sources</h2><ul><li><a href="https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/financial-supports" rel="noopener">gov.bc.ca: Financial supports for children and youth with support needs</a></li><li><a href="https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/faq-families-eligible-for-autism-funding" rel="noopener">gov.bc.ca: FAQ for families eligible for Autism Funding</a></li><li><a href="https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/autism-spectrum-disorder/autism-funding/funding-amount" rel="noopener">gov.bc.ca: How much funding is available</a></li></ul>'+SHARE.format(url=SITE+'/funding/autism-funding-2027.html',text='BC Autism Funding ends March 31, 2027. Here is what replaces it, in plain language:')+'<p><a class="pill lg" href="../quiz.html">See what your family qualifies for</a></p>'
page('funding/autism-funding-2027.html','BC Autism Funding ends March 31, 2027: what replaces it','BC Autism Funding ends March 31, 2027. Plain-language guide to the new Disability Benefit ($6,500 or up to $17,000) and Disability Supplement (up to $6,000), and what to do now.',exb,[{"@context":"https://schema.org","@type":"Article","headline":"BC Autism Funding ends March 31, 2027: what replaces it","datePublished":"2026-10-17","dateModified":"2026-10-17","author":{"@type":"Person","name":"Garett Oswald"},"mainEntityOfPage":SITE+"/funding/autism-funding-2027.html","image":SITE+"/og/og-2027.png"},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in EXF]}],og='og-2027.png')
home=f'''<section class="hero photo"><picture><source type="image/webp" srcset="img/cheam-800.webp 800w, img/cheam-1600.webp 1600w" sizes="100vw"><img src="img/cheam-1600.jpg" srcset="img/cheam-800.jpg 800w, img/cheam-1600.jpg 1600w" sizes="100vw" width="1600" height="900" alt="Snow-capped Mount Cheam above evergreen forest near Chilliwack, BC" fetchpriority="high"></picture><p class="trust"><span role="img" aria-label="Canada">🇨🇦</span> Made in Chilliwack, BC · by a dad of a non-verbal son</p><h1>Your child may qualify for thousands in support.</h1><p class="sub">Find out in 2 minutes. Free and private. No login.</p><p><a class="pill lg" href="quiz.html">Find what your family qualifies for</a></p><p class="small"><a href="directory/index.html">Or browse {len(L)} tools and services ›</a> · <a href="provinces/index.html">Not in BC? Pick your province ›</a></p><p class="photo-credit">Photo: <a href="credits.html">Mt. Cheam, Agassizlabs (CC0)</a></p></section><a class="urgent" href="funding/autism-funding-2027.html"><span class="badge warn">BC deadline</span><h2>BC Autism Funding ends March 31, 2027.</h2><p>Here’s what replaces it, and what to do now.</p><span class="more-link">Read the 2-minute explainer ›</span></a>{provbox("")}<a class="feature dtc-card" href="funding/dtc/index.html"><span class="badge">New</span><h2>The DTC Playbook.</h2><p class="sub">The Disability Tax Credit (DTC) opens the door to most other help, in every province. Step-by-step help, a sheet to bring to the doctor, and how to claim up to 10 years back.</p><span class="pill">Open the playbook</span></a><section class="feature" aria-labelledby="sb"><span class="badge">Coming soon</span><h2 id="sb">Speakboard: coming end of October</h2><p class="sub">An AAC app (an app that helps kids talk with pictures and voice) for iPhone and iPad. Built by a BC dad for his non-verbal son. Made by the founder of this site.</p><div class="sb-form">{mlform(SB_URL,"sb-home","Get notified","Email me when Speakboard launches")}</div></section><section class="band"><div class="cards3"><a class="tile" href="funding/disability-tax-credit.html"><h2>Start with the DTC.</h2><p>One form that opens the door to most other money.</p><span>Learn more ›</span></a><a class="tile" href="funding/autism-funding.html"><h2>BC Autism Funding is changing.</h2><p>It ends March 31, 2027. Here’s what’s next.</p><span>Learn more ›</span></a><a class="tile" href="funding/jordans-principle.html"><h2>Jordan’s Principle.</h2><p>Help for First Nations kids, on or off reserve.</p><span>Learn more ›</span></a></div></section>'''
page('index.html',NAME+': disability funding guide and autism tools for Canadian families','Free plain-language guide for Canadian parents of kids with autism and disabilities. Funding quiz, checklists for BC and every province, AAC apps and sensory tools.',home,[{"@context":"https://schema.org","@type":"WebSite","name":NAME,"url":SITE}])
quiz=f'''<div class="head"><h1>What can you get?</h1><p class="sub">9 quick questions. Your answers stay on your device.</p></div><form id="quiz"><fieldset><legend>Where do you live?</legend><label class="sel">Province or territory<select name="prov" class="prov-select" required>{PROVSEL}</select></label></fieldset><fieldset><legend>How old is your child?</legend><label><input type="radio" name="age" value="u6" required> Under 6</label><label><input type="radio" name="age" value="6to17"> 6–17</label><label><input type="radio" name="age" value="17h"> 17½ or older</label></fieldset><fieldset><legend>Does your child have an autism diagnosis?</legend><label><input type="radio" name="asd" value="y" required> Yes</label><label><input type="radio" name="asd" value="n"> No / not yet</label></fieldset><fieldset><legend>Is your child approved for the Disability Tax Credit (DTC)?</legend><label><input type="radio" name="dtc" value="y" required> Yes</label><label><input type="radio" name="dtc" value="n"> No</label><label><input type="radio" name="dtc" value="u"> Not sure</label></fieldset><fieldset><legend>Is your child First Nations?</legend><label><input type="radio" name="fn" value="y" required> Yes</label><label><input type="radio" name="fn" value="n"> No</label></fieldset><fieldset><legend>Do you live on reserve?</legend><label><input type="radio" name="res" value="y"> Yes</label><label><input type="radio" name="res" value="n" checked> No</label></fieldset><fieldset><legend>Does your family get income or disability assistance from your province?</legend><label><input type="radio" name="ia" value="y" required> Yes</label><label><input type="radio" name="ia" value="n"> No</label></fieldset><fieldset><legend>Does your child need a lot of help with eating, dressing, using the toilet, or washing?</legend><label><input type="radio" name="adl" value="y" required> Yes, with 3 or more</label><label><input type="radio" name="adl" value="n"> No / fewer</label></fieldset><fieldset><legend>Do you rent?</legend><label><input type="radio" name="rent" value="y" required> Yes</label><label><input type="radio" name="rent" value="n"> No</label></fieldset><button type="submit" class="pill">Show my checklist</button></form><section id="result" hidden><div class="summary" aria-live="polite"><p class="big" id="sum-count"></p><p class="money" id="sum-money"></p><p class="note" id="sum-note"></p></div><a class="feature dtc-card" href="funding/dtc/index.html"><span class="badge">Start here</span><h2>The DTC Playbook.</h2><p>Most help on this list needs the Disability Tax Credit first. Step-by-step help, a sheet for the doctor, and up to 10 years of back pay.</p><span class="pill">Open the playbook</span></a><h2>Your checklist</h2><ol id="checklist"></ol><p><button type="button" class="pill ghost" onclick="window.print()">Print / save as PDF</button></p><div class="feature sb-form">{mlform(NL_URL,"quiz-em","Email me","Get funding deadlines and reminders for your checklist by email")}</div>{SHARE.format(url=SITE+"/quiz.html",text="I found out what my child may qualify for in 2 minutes. Free for Canadian parents:")}</section><script src="quiz.js"></script>'''
page('quiz.html','What can your family get? Free 2-minute funding quiz for Canadian parents','9 quick questions build a checklist of federal and provincial programs for your child with a disability. BC and every province. Free, private, no login.',quiz,og='og-quiz.png')
faqs=[("What should I apply for first?","Usually the Disability Tax Credit (DTC). Once it’s approved, you can get the Child Disability Benefit, RDSP grants and bonds, and in BC, the new disability supplement."),("Does autism qualify for the Disability Tax Credit?","It can. It depends on how much autism affects your child’s daily life. A medical practitioner (like a doctor) must fill in Form T2201. A diagnosis alone is not enough."),("Is BC Autism Funding ending?","Yes. It ends March 31, 2027. Two new programs replace it. The BC Children and Youth Disability Benefit is based on your child’s needs ($6,500, or up to $17,000 a year). The supplement is based on family income (up to $6,000 a year). You can still apply for Autism Funding until March 2027."),("I don’t live in BC. Can this site help?","Yes. Federal programs like the DTC, Child Disability Benefit and RDSP work everywhere in Canada. Pick your province to see local programs. We only show dollar amounts we checked on an official page."),("Can I get the RDSP bond if I’m on assistance?","The bond is based on family income. You don’t have to put in any money. For 2026, you get the full $1,000 if your family net income is $38,237 or less. In BC, an RDSP doesn’t count against your assistance savings limit. Check with the ministry to be sure."),("Can I get BC rent help (RAP) while on income assistance?","Usually no, because both help with housing costs. The exception is Medical Services Only."),("Is Jordan’s Principle only for kids on reserve?","No. It covers First Nations kids on and off reserve. Call 1-855-572-4453, any time, day or night."),("Do I have to file taxes if I have no income?","Yes. The Canada Child Benefit, Child Disability Benefit, BC Family Benefit and RDSP bond all depend on filing your taxes every year."),("Are listings in the directory endorsements?","No. Listings are information only. We check that each official website works. We don’t test products.")]
fb=''.join(f'<h2>{E(q)}</h2><p>{E(a)}</p>' for q,a in faqs)
page('faq.html','FAQ: disability benefits and autism funding for families in Canada','Simple answers for parents about the DTC, BC autism funding changes, the RDSP, Jordan\'s Principle, housing, and other provinces.',f'<h1>Frequently asked questions</h1>{fb}',[{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in faqs]}])
page('about.html','About','Built by a Chilliwack BC parent with lived experience.','<h1>About</h1><p class="draft">[DRAFT, waiting for Garett\'s approval]</p><p>Hi, I\'m Garett, a dad in Chilliwack, BC. My son is autistic and non-verbal. I\'ve spent years working through forms, phone lines and waitlists, and I built this so other parents don\'t have to start from zero. [Garett: add your story in your own words.]</p><p>Find me on X: <a href="https://x.com/Gcarsona99">@Gcarsona99</a>.</p><p>This site is independent and isn\'t connected to any government.</p>')
page('credits.html','Credits','Photo and image credits for Family Funding & Tools.','<h1>Credits</h1><div class="credits"><h2>Header photo</h2><p><img src="img/cheam-800.jpg" width="800" height="450" alt="Mount Cheam seen from Agassiz, BC" loading="lazy"></p><p><strong>Mt. Cheam BC</strong> (Mount Cheam as seen from Agassiz, BC, 2023) by <a href="https://commons.wikimedia.org/wiki/User:Agassizlabs">Agassizlabs</a>, via <a href="https://commons.wikimedia.org/wiki/File:Mt._Cheam_BC.png">Wikimedia Commons</a>.</p><p>License: <a href="https://creativecommons.org/publicdomain/zero/1.0/">CC0 1.0 Public Domain Dedication</a>. No attribution is required, but we credit it with thanks. The image was cropped and resized for this site.</p><h2>Other graphics</h2><p>The treeline divider and layout are original to this site. The Canada flag is your device’s standard emoji. No government logos are used; this is not a government website.</p></div>')
page('disclaimer.html','Disclaimer','Not legal, medical or financial advice.','<h1>Disclaimer</h1><p>This site gives general information in plain language. It is not legal, medical, tax or money advice. It is not a government website. Programs and amounts change, so always check the official link on each page. Directory listings are not endorsements. The quiz runs only in your browser. It doesn’t send or save your answers. We only save the province you pick, on your own device.</p>')
sub='''<h1>Submit or feature your listing</h1><p>Make AAC apps, sensory or safety products, or run a BC service or support group? Get listed.</p><table><caption>Draft pricing (coming soon; payments are not on yet)</caption><thead><tr><th scope="col">Tier</th><th scope="col">Price</th><th scope="col">Includes</th></tr></thead><tbody><tr><td>Basic</td><td>Free</td><td>Standard listing after review</td></tr><tr><td>Featured</td><td>$49–149/mo (draft)</td><td>Top of category, badge, logo. Marked “Sponsored”</td></tr><tr><td>Newsletter sponsor</td><td>TBD (draft)</td><td>One clearly labelled sponsor spot per weekly issue</td></tr></tbody></table><p>Paid placement never changes our funding information, and every paid listing is clearly labelled.</p><h2>Submission form (coming soon)</h2><form onsubmit="event.preventDefault();this.querySelector('output').textContent='Thanks! Submissions open soon (not connected yet).'"><label>Organization / product name<input type="text" name="name" required></label><label>Official website<input name="url" type="url" required></label><label>Category<select name="cat"><option>AAC apps &amp; devices</option><option>Communication help (free)</option><option>Sensory products</option><option>Safety products</option><option>BC autism service providers</option><option>Support groups &amp; organizations</option></select></label><label>Region<input type="text" name="region"></label><label>Contact email<input name="email" type="email" required></label><label>Short description<textarea name="desc" maxlength="300"></textarea></label><button type="submit" class="pill">Submit</button><output aria-live="polite"></output></form>'''
page('submit.html','Submit or feature your listing','List your autism or special-needs tool or service for Canadian families.',sub)
